<?php require_once 'includes/auth.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=strtolower(trim($_POST['email']??''));if(filter_var($email,FILTER_VALIDATE_EMAIL)){$pdo->prepare("INSERT IGNORE INTO newsletter_subscribers(email) VALUES(?)")->execute([$email]);flash('success','You’re on the list.');}else flash('error','Please enter a valid email.');}header('Location: '.($_SERVER['HTTP_REFERER']??'index.php'));exit;